 if(out.parcel_id)One(db,"UPDATE housing_crate_locations SET location_kind=3,character_id=NULL,slot_id=NULL,custody_id=NULL,parcel_id="+I(out.parcel_id)+" WHERE crate_id="+I(b.crate_id)+" AND location_kind=2 AND custody_id="+id);else One(db,"UPDATE housing_crate_locations SET location_kind=1,character_id="+I(expected_owner)+",slot_id="+I(out.destination_slot)+",custody_id=NULL WHERE crate_id="+I(b.crate_id)+" AND location_kind=2 AND custody_id="+id);One(db,"UPDATE housing_crate_instances SET revision=revision+1 WHERE crate_id="+I(b.crate_id)+" AND revision="+I(b.revision)+" AND packed=0");One(db,"UPDATE housing_native_estates SET active=0 WHERE native_id="+I(b.native_estate_id)+" AND parent_native_id="+I(b.parent_native_estate_id)+" AND active=1");if(scope)One(db,"DELETE FROM housing_house_item_scopes WHERE custody_id="+id+" AND house_id="+I(scope->house_id)+" AND revision="+I(scope->revision));if(storage.revision)One(db,"DELETE FROM housing_live_item_storage WHERE custody_id="+id+" AND revision="+I(storage.revision));One(db,"DELETE FROM housing_live_placed_items WHERE custody_id="+id+" AND native_item_id="+I(placement.reservation.native_item_id));One(db,"UPDATE housing_live_placement_reservations SET state=2,custody_id=NULL WHERE native_item_id="+I(placement.reservation.native_item_id)+" AND state=1 AND custody_id="+id);One(db,"DELETE FROM housing_live_item_custody WHERE custody_id="+id);
 auto expected=before;expected.binding.revision++;expected.binding.custody_id=0;if(out.parcel_id)expected.parcel_id=out.parcel_id;else{expected.inventory_character_id=expected_owner;expected.inventory_slot_id=out.destination_slot;}CrateBinding::Allocation delivered;if(out.parcel_id)delivered=ReturnParcels::ReadCrateUnderTransaction(db,out.parcel_id);else{auto after=CrateBinding::ReadCarriedUnderTransaction(db,out.after);Require(bool(after),Error::Conflict);delivered=after.value;}out.allocation_after=CrateBinding::EncodeAllocation(delivered);Require(out.allocation_after==CrateBinding::EncodeAllocation(expected));auto empty=CrateBinding::ValidateMembersUnderTransaction(db,delivered);Require(bool(empty)&&empty.value==0);
 auto raw=H(CustodyCodec::Encode(out.before)),post=H(CustodyCodec::Encode(out.after)),state=H(out.source_state);if(!out.parcel_id)One(db,"INSERT INTO housing_offline_return_items(estate_id,custody_id,owner_character_id,account_id,destination_slot,source_kind,native_item_id,crate_id,allocation_before,allocation_after,row_before,row_after,state_before,before_sha256,after_sha256,state_sha256,returned_epoch) VALUES("+I(estate)+","+id+","+I(expected_owner)+","+I(out.account)+","+I(out.destination_slot)+",3,"+I(placement.reservation.native_item_id)+","+I(b.crate_id)+",x'"+H(out.allocation_before)+"',x'"+H(out.allocation_after)+"',x'"+raw+"',x'"+post+"',x'"+state+"',UNHEX(SHA2(x'"+raw+"',256)),UNHEX(SHA2(x'"+post+"',256)),UNHEX(SHA2(x'"+state+"',256)),UNIX_TIMESTAMP())");return out;
